import z3

def search_counterexample(n, target_r, target_rd):
    s = z3.Solver()
    adj = [[z3.Bool(f'e_{i}_{j}') for j in range(n)] for i in range(n)]
    for i in range(n):
        s.add(z3.Not(adj[i][i]))
        for j in range(n):
            s.add(adj[i][j] == adj[j][i])
    dist = [[z3.Int(f'd_{i}_{j}') for j in range(n)] for i in range(n)]
    for i in range(n):
        for j in range(n):
            s.add(dist[i][j] >= 0, dist[i][j] <= n)
            if i == j:
                s.add(dist[i][j] == 0)
            else:
                s.add(dist[i][j] >= 1)
                s.add(z3.Implies(adj[i][j], dist[i][j] == 1))
                for k in range(n):
                    s.add(dist[i][j] <= dist[i][k] + dist[k][j])
    for i in range(n):
        for j in range(n):
            if i != j:
                s.add(z3.Implies(dist[i][j] == 1, adj[i][j]))
                conds = [z3.And(adj[i][k], dist[k][j] == dist[i][j] - 1) for k in range(n) if k != i]
                s.add(z3.Or(dist[i][j] == 1, z3.Or(conds)))
    for i in range(n):
        for j in range(n):
            s.add(dist[i][j] <= n - 1)
    for v in range(n):
        s.add(z3.Or([dist[v][u] >= target_r for u in range(n)]))
    f = [z3.Int(f'f_{i}') for i in range(n)]
    for i in range(n):
        s.add(f[i] >= 0, f[i] <= 2)
        s.add(z3.Implies(f[i] == 0, z3.Or([z3.And(adj[i][j], f[j] == 2) for j in range(n) if j != i])))
    s.add(z3.Sum(f) <= target_rd)
    if s.check() == z3.sat:
        m = s.model()
        edges = [(i, j) for i in range(n) for j in range(i+1, n) if z3.is_true(m[adj[i][j]])]
        f_vals = [m[f[i]].as_long() for i in range(n)]
        print(f'FOUND SAT for n={n}, target_r={target_r}, target_rd={target_rd}!')
        print(f'Edges: {edges}')
        return edges
    else:
        print(f'UNSAT for n={n}, target_r={target_r}, target_rd={target_rd}')
        return None

# r=4, rd=4 for n=8..12
for n in range(8, 12):
